 }
 TabPage CreatorTab(string name){var p=new TabPage(name){BackColor=Color.White,Padding=new Padding(8)};creatorTabs.TabPages.Add(p);return p;}
 TableLayoutPanel CreatorLayout(TabPage p,int height){var t=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=1,RowCount=2};t.RowStyles.Add(new RowStyle(SizeType.Absolute,height));t.RowStyles.Add(new RowStyle(SizeType.Percent,100));p.Controls.Add(t);return t;}
 static string CreatorShort(string text){string line=(text??"").Split(new[]{'\r','\n'})[0];return line.Length>180?line.Substring(0,180)+"…":line;}
 DataGridView CreatorGrid(string[] headers){var g=new DataGridView{Dock=DockStyle.Fill,ReadOnly=true,AllowUserToAddRows=false,AllowUserToDeleteRows=false,MultiSelect=false,RowHeadersVisible=false,SelectionMode=DataGridViewSelectionMode.FullRowSelect,AutoSizeRowsMode=DataGridViewAutoSizeRowsMode.AllCells,BackgroundColor=Color.White};g.EnableHeadersVisualStyles=false;g.ColumnHeadersHeight=36;g.ColumnHeadersDefaultCellStyle.BackColor=navy;g.ColumnHeadersDefaultCellStyle.ForeColor=Color.White;g.DefaultCellStyle.WrapMode=DataGridViewTriState.True;g.RowTemplate.MinimumHeight=48;foreach(var h in headers)g.Columns.Add(h,h);foreach(DataGridViewColumn c in g.Columns)c.AutoSizeMode=DataGridViewAutoSizeColumnMode.Fill;return g;}
 void CreatorImport(bool video){if(busy)return;using(var d=new OpenFileDialog{Multiselect=true,Filter=video?"Video|*.mp4;*.mov;*.mkv;*.avi;*.wmv":"Kịch bản SRT|*.srt"})if(d.ShowDialog()==DialogResult.OK){if(video){creatorVideos.AddRange(d.FileNames);creatorVideos=creatorVideos.Distinct(StringComparer.OrdinalIgnoreCase).ToList();StateFiles.Write(Path.Combine(stateDir,"creator-videos.xml"),new XElement("videos",creatorVideos.Select(v=>new XElement("video",v))));}else AddFiles(d.FileNames);tabs.SelectedTab=creatorPage;RefreshCreator();}}
 void CreatorImportPaths(string[] paths){if(busy)return;var scripts=paths.Where(x=>Path.GetExtension(x).Equals(".srt",StringComparison.OrdinalIgnoreCase)).ToArray();if(scripts.Length>0)AddFiles(scripts);creatorVideos.AddRange(paths.Where(x=>new[]{".mp4",".mov",".mkv",".avi",".wmv"}.Contains(Path.GetExtension(x).ToLowerInvariant())&&File.Exists(x)));creatorVideos=creatorVideos.Distinct(StringComparer.OrdinalIgnoreCase).ToList();StateFiles.Write(Path.Combine(stateDir,"creator-videos.xml"),new XElement("videos",creatorVideos.Select(v=>new XElement("video",v))));tabs.SelectedTab=creatorPage;RefreshCreator();}
 void CreatorPair(){if(creatorProject==null||busy)return;using(var d=new OpenFileDialog{Filter="Video|*.mp4;*.mov;*.mkv;*.avi;*.wmv",Title="Ghép video cho "+Path.GetFileName(creatorProject.SourcePath)})if(d.ShowDialog()==DialogResult.OK){creatorProject.Video=d.FileName;foreach(var stage in creatorProject.Stages)stage.Reviewed=false;creatorProject.Save();RefreshCreator();}}
 void RefreshCreator(){if(creatorFiles==null||busy)return;StopCreatorVideo();string keep=creatorProject==null?"":creatorProject.SourcePath;creatorUpdating=true;try{creatorProjects.Clear();creatorFiles.Rows.Clear();foreach(var j in jobs.Where(j=>j.Timed&&j.State!=JobState.ImportFailed)){try{var p=CreatorProject.Open(j.InputPath,j.Cues,stateDir);if(p.Video.Length==0){p.Video=CreatorProject.Pair(j.InputPath,creatorVideos);if(p.Video.Length>0)p.Save();}creatorProjects.Add(p);int n=p.Stages.Count(s=>s.Key.Length>0&&!s.Success||s.Pending),r=p.Stages.Count(s=>s.Success&&s.NeedsReview&&!s.Reviewed);bool ready=File.Exists(p.Output);if(creatorFileFilter.SelectedIndex==1&&ready&&n==0&&r==0&&p.AttemptError.Length==0||creatorFileFilter.SelectedIndex==2&&!ready)continue;int row=creatorFiles.Rows.Add(Path.GetFileName(p.SourcePath),File.Exists(p.Video)?Path.GetFileName(p.Video):"Chưa ghép / cần chọn",p.Voice,p.Stages.Count+" / "+n+" / "+r,p.AttemptError.Length>0?"Lần chạy chưa đạt: "+CreatorShort(p.AttemptError):p.Output.Length>0&&File.Exists(p.Output)?p.Output:n>0?"Cần sửa / chưa xuất WAV":"Chưa đo");creatorFiles.Rows[row].Tag=p;creatorFiles.Rows[row].DefaultCellStyle.BackColor=n>0||p.AttemptError.Length>0?Color.MistyRose:r>0?Color.Cornsilk:Color.White;}catch(Exception ex){status.Text=j.Name+": "+ex.Message;}}int selected=creatorFiles.Rows.Cast<DataGridViewRow>().ToList().FindIndex(r=>((CreatorProject)r.Tag).SourcePath==keep);if(selected<0)selected=0;creatorProject=creatorFiles.Rows.Count>0?(CreatorProject)creatorFiles.Rows[selected].Tag:null;if(creatorProject!=null)creatorFiles.CurrentCell=creatorFiles.Rows[selected].Cells[0];creatorSummary.Text="Hàng đợi dùng chung: "+creatorProjects.Count+" SRT · "+creatorProjects.Sum(p=>p.Stages.Count(s=>!s.Success&&s.Key.Length>0||s.Pending))+" chặng cần sửa · "+creatorProjects.Count(p=>File.Exists(p.Output))+" WAV.\r\nGiọng chạy mới: "+catalog.Get(Key()).Name+" · giới hạn theo Tạo voice. Chặng V15.6, hơi thở riêng mỗi chặng; cân âm tổng có thể đổi mức âm.";}finally{creatorUpdating=false;}RefreshCreatorStages();}
 void CreatorSelectFile(int tab){if(creatorProject==null){status.Text="Thêm SRT vào hàng đợi trước.";return;}tabs.SelectedTab=creatorPage;creatorTabs.SelectedIndex=tab;RefreshCreatorStages();}
 void RefreshCreatorStages(){if(creatorStages==null)return;StopCreatorVideo();int keep=creatorStage==null?1:creatorStage.Source.Number;creatorUpdating=true;try{creatorStages.Rows.Clear();if(creatorProject!=null)foreach(var s in creatorProject.Stages){int filter=creatorFilter.SelectedIndex;bool bad=!s.Success||s.Pending,review=s.Success&&s.NeedsReview&&!s.Reviewed;if(filter==1&&!bad||filter==2&&!review||filter==3&&(bad||review))continue;int row=creatorStages.Rows.Add(s.Source.Number,Scripts.Stamp(s.Source.Start)+" → "+Scripts.Stamp(s.Source.End),s.Natural>0?s.Natural.ToString("0.000"):"Chưa đo",s.Natural>0?s.Measured.ToString("0.000"):"Chưa đo",s.Natural>0?s.Speed.ToString("0.000")+"x":"—",s.Natural>0?s.Tail.ToString("0.000"):"—",s.Pending?"Đã lưu sửa · cần chạy lại":CreatorShort(s.Status));creatorStages.Rows[row].Tag=s;creatorStages.Rows[row].DefaultCellStyle.BackColor=bad?Color.MistyRose:review?Color.Cornsilk:Color.FromArgb(228,246,238);}
   int idx=creatorStages.Rows.Cast<DataGridViewRow>().ToList().FindIndex(r=>((CreatorStage)r.Tag).Source.Number==keep);if(idx<0)idx=0;creatorStage=creatorStages.Rows.Count>0?(CreatorStage)creatorStages.Rows[idx].Tag:null;if(creatorStage!=null)creatorStages.CurrentCell=creatorStages.Rows[idx].Cells[0];}finally{creatorUpdating=false;}CreatorDetail();}
 void CreatorDetail(){if(creatorStage==null){creatorDetail.Text="Chọn chặng ở Chất lượng.";return;}creatorDetail.Text=Path.GetFileName(creatorProject.SourcePath)+" · Chặng "+creatorStage.Source.Number+"\r\n"+Scripts.Stamp(creatorStage.Source.Start)+" → "+Scripts.Stamp(creatorStage.Source.End)+"\r\nGiọng lần đo: "+creatorProject.Voice+"\r\nGốc: "+creatorStage.Natural.ToString("0.000")+"s · sau căn: "+creatorStage.Measured.ToString("0.000")+"s\r\nTốc độ: "+creatorStage.Speed.ToString("0.000")+"x · nghỉ cuối "+creatorStage.Tail.ToString("0.000")+"s\r\n"+creatorStage.Status+"\r\n\r\n"+creatorStage.Text;creatorSubtitle.Text=creatorStage.Text;creatorUpdating=true;try{creatorBefore.Text=creatorStage.RenderedText.Length>0?creatorStage.RenderedText:creatorStage.Source.Text;creatorEdit.Text=creatorStage.Draft.Length>0?creatorStage.Draft:creatorStage.Text;creatorTrialInfo.Text="Khung "+creatorStage.Source.Budget.ToString("0.000")+"s · "+creatorStage.Status;}finally{creatorUpdating=false;}try{creatorPreviewWave=File.Exists(creatorStage.Audio)?Wave.Read(creatorStage.Audio):null;}catch{creatorPreviewWave=null;}if(creatorStage.TrialKey==CreatorRenderer.Key(creatorProject,creatorStage,creatorProject.Signature,creatorEdit.Text.Trim())&&creatorStage.TrialInfo.Length>0)creatorTrialInfo.Text=creatorStage.TrialInfo+(creatorStage.Pending?" · Đã lưu, cần chạy lại để ghép WAV.":"");creatorWave.Invalidate();}
 void CreatorReviewed(){if(creatorStage==null||!creatorStage.Success||creatorStage.Pending){status.Text="Chỉ duyệt khoảng nghỉ của chặng đã đo đạt. Chặng tràn vẫn cần sửa.";return;}creatorStage.Reviewed=!creatorStage.Reviewed;creatorProject.Save();RefreshCreatorStages();}
 void CreatorRestoreSettings(){try{if(creatorProject==null||creatorProject.Settings.Length==0)throw new Exception("Chưa lưu thiết lập lần đo.");Apply(VoiceSettings.From(XElement.Parse(creatorProject.Settings)));status.Text="Đã nạp thiết lập giọng lần đo; áp dụng chung cho hàng đợi.";}catch(Exception ex){Error(ex);}}
 void CreatorShowVideo(){if(creatorStage==null)return;StopCreatorVideo();tabs.SelectedTab=creatorPage;creatorTabs.SelectedIndex=2;CreatorDetail();}
 void CreatorShowEdit(){if(creatorStage==null)return;StopCreatorVideo();tabs.SelectedTab=creatorPage;creatorTabs.SelectedIndex=3;CreatorDetail();}
 void CreatorAdjacent(int direction){var visible=creatorFiles.Rows.Cast<DataGridViewRow>().ToList();if(visible.Count==0)return;int n=visible.FindIndex(r=>r.Tag==creatorProject);n=(n+direction+visible.Count)%visible.Count;creatorFiles.CurrentCell=visible[n].Cells[0];creatorProject=(CreatorProject)visible[n].Tag;creatorFilter.SelectedIndex=0;RefreshCreatorStages();}
 void CreatorAccept(bool next){if(creatorStage==null||busy)return;try{creatorStage.Draft=creatorEdit.Text;creatorProject.Accept(creatorStage);if(next){var all=creatorProjects.SelectMany(p=>p.Stages.Select(s=>Tuple.Create(p,s))).ToList();int at=all.FindIndex(t=>t.Item1==creatorProject&&t.Item2==creatorStage);var hit=all.Skip(at+1).Concat(all.Take(at)).FirstOrDefault(t=>t.Item2.Key.Length>0&&!t.Item2.Success&&!t.Item2.Pending);if(hit!=null){creatorProject=hit.Item1;creatorStage=hit.Item2;creatorFilter.SelectedIndex=0;RefreshCreatorStages();creatorStage=hit.Item2;CreatorDetail();}}else CreatorDetail();status.Text="Đã lưu bản sửa. Bấm Chạy lại các chặng đã sửa ở Hàng đợi để ghép WAV.";}catch(Exception ex){Error(ex);}}
 void CreatorSaveSrt(){if(creatorProject==null)return;try{if(creatorProject.Stages.Any(s=>s.Draft.Length>0&&s.Draft!=s.Text))throw new Exception("Lưu bản sửa trước khi xuất SRT.");using(var d=new SaveFileDialog{Filter="SRT|*.srt",FileName=Path.GetFileNameWithoutExtension(creatorProject.SourcePath)+".edited.srt",OverwritePrompt=true})if(d.ShowDialog()==DialogResult.OK){if(Path.GetFullPath(d.FileName)==Path.GetFullPath(creatorProject.SourcePath))throw new Exception("Chọn tên khác để giữ SRT nguồn.");File.WriteAllText(d.FileName,Scripts.ToSrt(creatorProject.Stages.Select(s=>new Cue{Id=s.Source.Number,Start=s.Source.Start,End=s.Source.End,Text=s.Text}).ToList()),new UTF8Encoding(false));}}catch(Exception ex){Error(ex);}}
 async Task CreatorTry(){if(creatorStage==null||busy)return;var p=creatorProject;var s=creatorStage;string text=creatorEdit.Text;StopCreatorVideo();if(player!=null){player.Stop();player.Dispose();player=null;}try{var o=OptionsForRun(false);o.ReportContext=ReportContext(p.SourcePath,p.Sources);o.ReportContext.Purpose="Đo thử riêng chặng "+s.Source.Number;active=NewEngine();active.Archive=new SpeechArchive(stateDir){Refresh=true};SetBusy(true);var engine=active;await Task.Run(()=>CreatorRenderer.Trial(p,s,engine,o,text));creatorTrialInfo.Text=s.TrialInfo;status.Text="Đã tạo thử chặng; chưa thay bản A và chưa xuất WAV tổng.";}catch(OperationCanceledException){status.Text="Đã dừng tạo thử chặng.";}catch(Exception ex){Error(ex);}finally{if(active!=null)active.Dispose();active=null;SetBusy(false);}}
 async Task RunCreator(bool repairsOnly){if(busy)return;StopCreatorVideo();var input=creatorProjects.Where(p=>!repairsOnly||p.Stages.Any(s=>s.Pending)).ToList();if(input.Count==0){status.Text=repairsOnly?"Chưa có chặng đã lưu sửa để chạy lại.":"Thêm SRT trước khi chạy.";return;}int done=0,failed=0;bool stopped=false;if(player!=null){player.Stop();player.Dispose();player=null;}try{SetBusy(true);foreach(var p in input){var o=OptionsForRun(false);o.ReportContext=ReportContext(p.SourcePath,p.Sources,jobs.FirstOrDefault(j=>j.InputPath==p.SourcePath));o.ReportContext.Purpose="Duyệt video / sửa chặng V15.6";active=NewEngine();active.Archive=new SpeechArchive(stateDir);var engine=active;try{if(repairsOnly&&p.Signature!=CreatorRenderer.Signature(engine,o))throw new Exception("Thiết lập đã đổi. Nạp thiết lập lần đo hoặc chạy toàn bộ.");p.Voice=catalog.Get(Key()).Name;if(!repairsOnly)p.Settings=CaptureSettings().Xml().ToString();await Task.Run(()=>CreatorRenderer.Run(p,engine,o,repairsOnly,(n,m)=>ShowActivity(Path.GetFileName(p.SourcePath)+" · "+m)));done++;}catch(OperationCanceledException){stopped=true;break;}catch(Exception ex){failed++;status.Text=Path.GetFileName(p.SourcePath)+": "+ex.Message;}finally{var job=jobs.FirstOrDefault(j=>j.InputPath==p.SourcePath);if(job!=null){job.ReportPath=p.Report;job.OutputPath=p.Output;job.State=File.Exists(p.Output)?JobState.Done:engine.Cancelled?JobState.Cancelled:JobState.Failed;job.Error=p.AttemptError;job.AudioDuration=File.Exists(p.Output)?p.Sources.Last().End:0;job.DurationFinal=File.Exists(p.Output);job.Warning=p.Stages.Any(s=>s.NeedsReview&&!s.Reviewed)?"Có chặng cần nghe duyệt":"";}engine.Dispose();active=null;}}status.Text=(stopped?"Đã dừng · ":"")+"Duyệt hàng đợi: "+done+" WAV xong · "+failed+" file cần xử lý. Xem Chất lượng và báo cáo từng file.";}catch(Exception ex){Error(ex);}finally{if(active!=null)active.Dispose();active=null;SetBusy(false);RefreshJobs();RefreshCreator();SaveSession();}}
 void StopCreatorVideo(){if(reviewTimer!=null)reviewTimer.Stop();if(reviewTransport!=null)try{reviewTransport.Pause();}catch{}reviewTransport=null;}
 void CreatorPlay(){try{if(creatorStage==null||!File.Exists(creatorProject.Video))throw new Exception("Ghép video cho SRT này ở Hàng đợi trước khi nghe cùng video.");if(reviewTransport!=null){if(reviewTransport.Playing)reviewTransport.Pause();else{reviewTransport.Play();reviewTimer.Start();}return;}if(Environment.OSVersion.Platform!=PlatformID.Win32NT)throw new Exception("Xem video nhúng cần Windows Media Player Legacy trên Windows. Audio A/B vẫn có thể nghe riêng.");if(reviewVideo==null){creatorVideoPanel.Controls.Clear();reviewVideo=new ReviewMediaHost{Dock=DockStyle.Fill};reviewAudio=new ReviewMediaHost{Width=1,Height=1,Left=0,Top=0};((System.ComponentModel.ISupportInitialize)reviewVideo).BeginInit();((System.ComponentModel.ISupportInitialize)reviewAudio).BeginInit();creatorVideoPanel.Controls.Add(reviewVideo);creatorVideoPanel.Controls.Add(reviewAudio);((System.ComponentModel.ISupportInitialize)reviewVideo).EndInit();((System.ComponentModel.ISupportInitialize)reviewAudio).EndInit();var a=reviewVideo.Handle;var b=reviewAudio.Handle;reviewAudio.SendToBack();}reviewTransport=new ReviewTransport(reviewVideo,reviewAudio){NewVoice=creatorVoiceMode.SelectedIndex==0,Loop=creatorLoop.Checked};creatorPlayingAudio=creatorStage.Audio;double length=File.Exists(creatorPlayingAudio)?FinalAudio.PcmFrames(creatorPlayingAudio)/24000.0:0;reviewTransport.Load(creatorProject.Video,creatorPlayingAudio,creatorStage.Source.Start,creatorStage.Source.End,length);reviewTransport.Play();reviewTimer.Start();}catch(Exception ex){StopCreatorVideo();Error(new Exception("Không mở được bộ phát: "+ex.Message+"\r\nNếu thiếu Windows Media Player Legacy / Media Feature Pack, bật thành phần này trong Windows.",ex));}}
 void CreatorTick(){try{if(reviewTransport==null)return;reviewTransport.Loop=creatorLoop.Checked;reviewTransport.SetVolume(creatorVolume.Value);reviewTransport.Tick();double pos=reviewTransport.Position;creatorClock.Text=Scripts.Stamp(pos);if(creatorStage!=null){double range=Math.Max(creatorStage.Source.Budget,creatorStage.Measured);creatorSeek.Value=Math.Max(0,Math.Min(1000,(int)((pos-creatorStage.Source.Start)/range*1000)));}creatorWave.Invalidate();}catch(Exception ex){StopCreatorVideo();status.Text="Bộ phát: "+ex.Message;}}
 void CreatorDraw(Graphics g){if(creatorStage==null)return;var r=creatorWave.ClientRectangle;g.DrawString("Mốc nguồn "+Scripts.Stamp(creatorStage.Source.Start)+" → "+Scripts.Stamp(creatorStage.Source.End)+" · waveform chặng (chưa cân âm tổng)",Font,Brushes.SlateGray,8,3);double max=Math.Max(creatorStage.Source.Budget,creatorStage.Measured);int left=8,width=Math.Max(1,r.Width-16),mid=58;try{if(creatorPreviewWave!=null){var w=creatorPreviewWave;for(int x=0;x<width;x++){int i=(int)(x/(double)width*max*w.Rate);if(i>=w.Samples.Length)break;int peak=0;for(int j=i;j<Math.Min(w.Samples.Length,i+Math.Max(1,w.Samples.Length/width));j+=4)peak=Math.Max(peak,Math.Abs((int)w.Samples[j]));float h=peak/32768f*25;g.DrawLine(x/(double)width*max>creatorStage.Source.Budget?Pens.Crimson:Pens.Teal,left+x,mid-h,left+x,mid+h);}}}catch{}int end=left+(int)(width*creatorStage.Source.Budget/max);g.DrawLine(Pens.Crimson,end,25,end,r.Height);if(reviewTransport!=null)try{int x=left+(int)((reviewTransport.Position-creatorStage.Source.Start)/max*width);g.DrawLine(Pens.Blue,x,25,x,r.Height);}catch{}}
}}
